UPDATE patients
SET avatar = #{avatar}
WHERE patient_id = #{patientId}

update patients
set
    balance=#{balance}
where
    patient_id=#{patientId}

UPDATE patients
SET balance = CAST(balance AS DECIMAL(12,2)) - #{fee}
WHERE patient_id = #{patientId}
  AND CAST(balance AS DECIMAL(12,2)) >= #{fee}

UPDATE patients
SET phone = #{phone}, balance = #{balance}, email = #{email}
WHERE patient_id = #{patientId}

update patients
set
    password=NULL,
    password_hash=#{1}
where
    name=#{0}

